import{_ as t,c as a,o as e,a2 as r}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"Translation Traits","description":"","frontmatter":{"sidebarPos":13,"sidebarTitle":"Translation Traits","sidebarGroupTitle":"Translation Traits"},"headers":[],"relativePath":"system-reference/backend/entity-traits/translation/overview.md","filePath":"system-reference/backend/entity-traits/translation/overview.md","lastUpdated":1785244667000}'),o={name:"system-reference/backend/entity-traits/translation/overview.md"},s=r('<h1 id="translation-traits" tabindex="-1">Translation Traits <a class="header-anchor" href="#translation-traits" aria-label="Permalink to &quot;Translation Traits&quot;">​</a></h1><p>Two traits handle multi-locale content. <code>HasTranslation</code> provides full translation storage backed by <code>astrotomic/laravel-translatable</code>. <code>IsTranslatable</code> is a lightweight detection helper. Opt-in SEO/robots/sitemap metadata is layered via <code>HasTranslatableMetadata</code>.</p><table><thead><tr><th>Trait</th><th>Description</th></tr></thead><tbody><tr><td><a href="./has-translation">HasTranslation</a></td><td>Multi-locale content via <code>astrotomic/laravel-translatable</code> with Modularous overrides</td></tr><tr><td><a href="./is-translatable">IsTranslatable</a></td><td>Single-method helper that detects whether a model uses translations</td></tr><tr><td><code>HasTranslatableMetadata</code></td><td>Opt-in SEO + robots + sitemap fields (<code>src/Entities/Traits/HasTranslatableMetadata.php</code>)</td></tr></tbody></table><h2 id="repository-companion-trait" tabindex="-1">Repository companion trait <a class="header-anchor" href="#repository-companion-trait" aria-label="Permalink to &quot;Repository companion trait&quot;">​</a></h2><p>When an entity (or content concern) uses <strong><code>HasTranslatableMetadata</code></strong>, its repository <strong>must</strong> also use <strong><code>Unusualify\\Modularous\\Repositories\\Traits\\TranslatableMetadataTrait</code></strong>.</p><p>SEO/metadata admin form inputs are appended via the repository (<code>appendFormSchemaTranslatableMetadataTrait</code>). Entity-only usage stores columns but breaks admin/form behavior.</p><p>On translated models, put <code>TranslationsTrait</code> <strong>before</strong> <code>TranslatableMetadataTrait</code> on the repository. See <a href="./../../repository-traits/content#translatablemetadatatrait">Content Repository Traits</a>.</p>',7),n=[s];function i(d,l,c,p,h,T){return e(),a("div",null,n)}const u=t(o,[["render",i]]);export{b as __pageData,u as default};
